#ifndef BCM_PIEZO_VOICE_H
#define BCM_PIEZO_VOICE_H

#include <stdint.h>

#define PIEZO_VOICE_RATE             22050u

/* Startup chime: short ascending three-tone sequence */
#define PIEZO_VOICE_STARTUP_SAMPLES  2205u  /* 100 ms */

/* Shutdown chime: descending tone */
#define PIEZO_VOICE_SHUTDOWN_SAMPLES 2205u

/* Charge chime: single soft ping */
#define PIEZO_VOICE_CHARGE_SAMPLES   1102u  /* 50 ms */

/* Forward declarations — arrays defined in bcm_piezo.c or generated .c */
extern const int16_t piezo_voice_startup[PIEZO_VOICE_STARTUP_SAMPLES];
extern const int16_t piezo_voice_shutdown[PIEZO_VOICE_SHUTDOWN_SAMPLES];
extern const int16_t piezo_voice_charge[PIEZO_VOICE_CHARGE_SAMPLES];

#endif /* BCM_PIEZO_VOICE_H */
